insert into public.conversations (session_id, user_message, bot_answer, sources, escalated, confidence)
values ($1, $2, $3, $4::jsonb, $5, $6)
returning id;

insert into public.escalations (session_id, question, reason, customer_email)
values ($1, $2, $3, $4)
returning id;

