// Body: { "session_id": string, "email": string } sent by the widget's email field.
let body = $json.body ?? {};
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = {};
  }
}

const sessionId = typeof body.session_id === 'string' ? body.session_id.trim() : '';
const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
const errors = [];

if (!/^[A-Za-z0-9_-]{8,64}$/.test(sessionId)) errors.push('session_id must be 8-64 characters: letters, digits, "-" or "_"');
if (email.length > 254 || !/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(email)) errors.push('email is not valid');

return [{ json: { valid: errors.length === 0, error: errors.join('; '), session_id: sessionId, email } }];
